// === Tab: mySketch ===
/*
  Based upon this Tutorial by Alexander Mordvintsev:
  Particle Lenia from scratch
  https://observablehq.com/@znah/particle-lenia-from-scratch

  The simulation shows Particle Lenia: the system of 
  particles that move to minimize local energy of their 
  interaction, leading to the formation of complex and 
  diverse structures. 

	https://arxiv.org/pdf/2305.16706

  This version by Juan Carlos Ponce Campuzano
  12/Jul/2024
  https://www.patreon.com/jcponce
*/

let params = {
  mu_k: 4.0, sigma_k: 1.0, w_k: 0.022,
  mu_g: 0.6, sigma_g: 0.15, c_rep: 1.0,
  dt: 0.1
};

let point_n = 200;
let points1, points2;
let fields1, fields2;
let steps_per_frame; // Adjust this based on desired speed
let randomCol1, randomCol2;
let changeInterval = 1000; // Change parameters every 1000 frames
let frameCount = 0;

function setup() {
  createCanvas(windowWidth, windowHeight);
  points1 = init(new Float32Array(point_n * 2), -6);  // Initialize closer to center
  points2 = init(new Float32Array(point_n * 2), 6);   // Initialize closer to center
  fields1 = {
    R_val: new Float32Array(point_n),
    U_val: new Float32Array(point_n),
    R_grad: new Float32Array(point_n * 2),
    U_grad: new Float32Array(point_n * 2)
  };
  fields2 = {
    R_val: new Float32Array(point_n),
    U_val: new Float32Array(point_n),
    R_grad: new Float32Array(point_n * 2),
    U_grad: new Float32Array(point_n * 2)
  };

  colorMode(RGB, 200, 200, 200, 200);
  noStroke();

  steps_per_frame = int(random(3, 12));

  randomCol1 = random();
  randomCol2 = random();
}

function draw() {
  for (let i = 0; i < steps_per_frame; ++i) step();
  background(0, 30);

  translate(width / 2, height / 2);
  scale(width / 45.0);
  strokeWeight(0.1);

  drawSystem(points1, fields1, randomCol1);
  drawSystem(points2, fields2, randomCol2);

  // Update parameters periodically
  frameCount++;
  if (frameCount % changeInterval === 0) {
    randomizeParams();
  }
}

function drawSystem(points, fields, randomCol) {
  for (let i = 0; i < point_n; ++i) {
    let x = points[i * 2], y = points[i * 2 + 1];
    let r = params.c_rep / (fields.R_val[i] * 5.0);

    if(randomCol < 0.3){
      fill((i)/point_n* 200, 70, 100);
    } else if(0.3 <= randomCol && randomCol < 0.6) {
      fill(90, 80, (i)/point_n* 200);
    } else {
      fill(20, (i)/point_n* 200, 180);
    }

    ellipse(x, y, r * 2, r * 2);
  }
}

function init(points, offsetX) {
  for (let i = 0; i < point_n; ++i) {
    points[i * 2] = (Math.random() - 0.5) * 12 + offsetX;
    points[i * 2 + 1] = (Math.random() - 0.5) * 12;
  }
  return points;
}

function add_xy(a, i, x, y, c) {
  a[i * 2] += x * c;
  a[i * 2 + 1] += y * c;
}

function compute_fields(pointsA, fieldsA, pointsB, fieldsB) {
  const { R_val: R_valA, U_val: U_valA, R_grad: R_gradA, U_grad: U_gradA } = fieldsA;
  const { R_val: R_valB, U_val: U_valB, R_grad: R_gradB, U_grad: U_gradB } = fieldsB;
  const { c_rep, mu_k, sigma_k, w_k } = params;

  R_valA.fill(repulsion_f(0.0, c_rep)[0]);
  U_valA.fill(peak_f(0.0, mu_k, sigma_k, w_k)[0]);
  R_gradA.fill(0);
  U_gradA.fill(0);

  R_valB.fill(repulsion_f(0.0, c_rep)[0]);
  U_valB.fill(peak_f(0.0, mu_k, sigma_k, w_k)[0]);
  R_gradB.fill(0);
  U_gradB.fill(0);

  for (let i = 0; i < point_n - 1; ++i) {
    for (let j = i + 1; j < point_n; ++j) {
      let rx = pointsA[i * 2] - pointsA[j * 2];
      let ry = pointsA[i * 2 + 1] - pointsA[j * 2 + 1];
      var r = Math.sqrt(rx * rx + ry * ry) + 1e-20;
      rx /= r;
      ry /= r;

      if (r < 1.0) {
        const [R, dR] = repulsion_f(r, c_rep);
        add_xy(R_gradA, i, rx, ry, dR);
        add_xy(R_gradA, j, rx, ry, -dR);
        R_valA[i] += R;
        R_valA[j] += R;
      }
      const [K, dK] = peak_f(r, mu_k, sigma_k, w_k);
      add_xy(U_gradA, i, rx, ry, dK);
      add_xy(U_gradA, j, rx, ry, -dK);
      U_valA[i] += K;
      U_valA[j] += K;
    }
  }

  for (let i = 0; i < point_n - 1; ++i) {
    for (let j = i + 1; j < point_n; ++j) {
      var rx = pointsB[i * 2] - pointsB[j * 2];
      var ry = pointsB[i * 2 + 1] - pointsB[j * 2 + 1];
      var r = Math.sqrt(rx * rx + ry * ry) + 1e-20;
      rx /= r;
      ry /= r;

      if (r < 1.0) {
        const [R, dR] = repulsion_f(r, c_rep);
        add_xy(R_gradB, i, rx, ry, dR);
        add_xy(R_gradB, j, rx, ry, -dR);
        R_valB[i] += R;
        R_valB[j] += R;
      }
      const [K, dK] = peak_f(r, mu_k, sigma_k, w_k);
      add_xy(U_gradB, i, rx, ry, dK);
      add_xy(U_gradB, j, rx, ry, -dK);
      U_valB[i] += K;
      U_valB[j] += K;
    }
  }

  // Cross-system interaction
  for (let i = 0; i < point_n; ++i) {
    for (let j = 0; j < point_n; ++j) {
      var rx = pointsA[i * 2] - pointsB[j * 2];
      var ry = pointsA[i * 2 + 1] - pointsB[j * 2 + 1];
      var r = Math.sqrt(rx * rx + ry * ry) + 1e-20;
      rx /= r;
      ry /= r;

      if (r < 1.0) {
        const [R, dR] = repulsion_f(r, c_rep);
        add_xy(R_gradA, i, rx, ry, dR);
        add_xy(R_gradB, j, -rx, -ry, dR);
        R_valA[i] += R;
        R_valB[j] += R;
      }
      const [K, dK] = peak_f(r, mu_k, sigma_k, w_k);
      add_xy(U_gradA, i, rx, ry, dK);
      add_xy(U_gradB, j, -rx, -ry, dK);
      U_valA[i] += K;
      U_valB[j] += K;
    }
  }
}

function repulsion_f(x, c_rep) {
  const t = Math.max(1.0 - x, 0.0);
  return [0.5 * c_rep * t * t, -c_rep * t];
}

function fast_exp(x) {
  var t = 1.0 + x / 32.0;
  t *= t;
  t *= t;
  t *= t;
  t *= t;
  t *= t;
  return t;
}

function peak_f(x, mu, sigma, w = 1.0) {
  var t = (x - mu) / sigma;
  const y = w / fast_exp(t * t);
  return [y, -2.0 * t * y / sigma];
}

function step() {
  const { R_val: R_val1, U_val: U_val1, R_grad: R_grad1, U_grad: U_grad1 } = fields1;
  const { R_val: R_val2, U_val: U_val2, R_grad: R_grad2, U_grad: U_grad2 } = fields2;
  const { mu_g, sigma_g, dt } = params;

  compute_fields(points1, fields1, points2, fields2);

  let total_E1 = 0.0;
  for (let i = 0; i < point_n; ++i) {
    const [G, dG] = peak_f(U_val1[i], mu_g, sigma_g);
    const vx = dG * U_grad1[i * 2] - R_grad1[i * 2];
    const vy = dG * U_grad1[i * 2 + 1] - R_grad1[i * 2 + 1];
    add_xy(points1, i, vx, vy, dt);
    total_E1 += R_val1[i] - G;
  }

  let total_E2 = 0.0;
  for (let i = 0; i < point_n; ++i) {
    const [G, dG] = peak_f(U_val2[i], mu_g, sigma_g);
    var vx = dG * U_grad2[i * 2] - R_grad2[i * 2];
    var vy = dG * U_grad2[i * 2 + 1] - R_grad2[i * 2 + 1];
    add_xy(points2, i, vx, vy, dt);
    total_E2 += R_val2[i] - G;
  }

  return (total_E1 + total_E2) / (2 * point_n);
}

function mousePressed() {
  randomizeParams();
  // Debugg
  //console.log(params);
}

function randomizeParams() {
  params.mu_k = random(1.0, 5.0);
  params.sigma_k = random(0.1, 2.0);
  params.w_k = random(0.01, 0.07);
  params.mu_g = random(0.1, 1.0);
  params.sigma_g = random(0.05, 0.3);
  params.c_rep = random(0.1, 2.0);
  // Debugg
  //console.log(params);
}

